package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for the add method of Complex class.
 */
public class Complex_add_TriageGen5Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testAdd_PositiveNumbers() throws NullArgumentException {
        Complex c1 = new Complex(1.5, 2.5);
        Complex c2 = new Complex(2.5, 3.5);
        Complex expected = new Complex(4.0, 6.0);
        Complex result = c1.add(c2);

        Assert.assertEquals("Real part should be 4.0", expected.getReal(), result.getReal(), EPSILON);
        Assert.assertEquals("Imaginary part should be 6.0", expected.getImaginary(), result.getImaginary(), EPSILON);
    }












}

