/**
 * Unit tests for the add method of Complex class.
 */
public class Complex_add_TriageGen5Test {

    private static final double EPSILON = 1e-10;









    @Test
    public void testAdd_Infinity() throws NullArgumentException {
        Complex c1 = new Complex(Double.POSITIVE_INFINITY, 0.0);
        Complex c2 = new Complex(1.0, 1.0);
        Complex result = c1.add(c2);

        Assert.assertTrue("Real part should be Infinity", Double.isInfinite(result.getReal()));
        Assert.assertEquals("Imaginary part should be 1.0", 1.0, result.getImaginary(), EPSILON);
    }




}

